import re
import os
import pprint
from message_type_mapping import physical_channel_message_type_mapping as old_physical_channel_message_type_mapping
from message_type_mapping import rrc_type_mapping as old_rrc_type_mapping


"""
This module uses dissector lua file (included in this package) as an input and parses out the the relevant RRC message types used by iphy.

NOTICE:
    Module MUST BE RUN each time significant changes in lua dissectors in wireshark occurs.

TO DO: add how to acquire *lua file for current WTS build.
USAGE:
    There is an unwanted overwrite protection (variable OVERWRITE). After the script runs please run stdout output with further instructions.
    To run execute:
        python dissector_parser.py
    If dissector file changed and new message types are added / existing are changed, new message_type_mapping.py file is generated.
"""

OVERWRITE = True

python_header = '''# -*- coding: utf-8 -*-
"""
:copyright: Nokia Networks
:author: Dawid Krawczuk
:contact: I_ABSTRACT_LIBRARY_DEV@internal.nsn.com
:maintainer: Dawid Krawczuk
:contact: dawid.krawczuk@nokia.com
"""
'''


def get_message_type_mapping():
    """
    Retuns dict of ue-usable message types (type number in decimal format, type name).
    :return: dict of supported types e.g. {'1' : 'NAME'}
    """
    hex_name_dict = _parse_message_types()
    return dict((int(str(int_id), 16), name) for (int_id, name) in list(hex_name_dict.items()))


def get_rrc_type_mapping():
    """Return dict that determines the rrc version from used iphy.protocol.type filed value"""
    rrc_type = _parse_rrc_type()
    return rrc_type


def _dissector_file_content():
    """
    Reads contents of dissector.lua file included in this repository.
    :return:
    """
    dissector_filename = 'dissector.lua'
    filename = os.path.join(os.path.split(__file__)[0], dissector_filename)
    out = None
    print(filename)
    with open(filename, 'r') as file:
        out = file.read()
    return out


def _removed_not_used_msg_types(message_types):
    """
    Only message not starting with 'CTRL' are accepted, others are not used.
    :param message_types: list of tuples [('0x00','NAME'),...,('0x01','NAME2'))
    :return: dict e.g. {'0x00' : 'NAME'}
    """
    supported_types = {}
    not_supported_rules = ['CTRL', 'SIM', 'CRLC', 'SHORT', 'ENDC']
    for (m_type, m_name) in message_types:
        supported_item = True
        for not_rule in not_supported_rules:
            if not_rule in m_name:
                supported_item = False
        if supported_item:
            supported_types[m_type] = m_name
    return supported_types


def _parse_message_types():
    """
    Returns filtered dict of usable message type (type in hex, type name).
    :return: dict of supported types e.g. {'0x00' : 'NAME'}
    """
    lua_message_type_var_name = "msg_type_to_name"
    type_getter = re.compile(r"%s\[(0x\S*?)\]\s=\s\"(\S+)\"" % lua_message_type_var_name)
    parsed_message_types = re.findall(type_getter, _dissector_file_content())
    return _removed_not_used_msg_types(parsed_message_types)


def _convert_tool_name_to_rrc_type(tool_name):
    if 'I-PHY' in tool_name:
        return 'rrc'
    else:
        return 'nr-rrc'


def _parse_rrc_type():
    """
    Parses from hex from::
    {[0x3233] = 'I-PHY PoC '}
    {[0x3433] = 'AirPhone PoC '}
    """
    rrc_type_getter = re.compile(r"\[(\S+)\]\s *=\s *\'(.*?PoC.*?)\'")
    parsed_rrc_types = re.findall(rrc_type_getter, _dissector_file_content())
    return dict((rrc_type[0], _convert_tool_name_to_rrc_type(rrc_type[1])) for rrc_type in parsed_rrc_types)


if __name__ == '__main__':
    message_types = get_message_type_mapping()
    rrc_mapping = get_rrc_type_mapping()
    if old_physical_channel_message_type_mapping != message_types or old_rrc_type_mapping != rrc_mapping:
        if not OVERWRITE:
            print('Message_type_mapping.py differs from existing one, but OVERWRITE is disabled. '
                  'Consider setting OVERWRITE=True if you really want to do this!!')
            exit(0)
        print('Writing new values to file..')
        with open('message_type_mapping.py', 'w') as out_file:
            out_file.write(python_header)
            out_file.write("physical_channel_message_type_mapping = {\n " + pprint.pformat(message_types, indent=4)[1:] + "\n\n")
            out_file.write("rrc_type_mapping = {\n " + pprint.pformat(rrc_mapping, indent=4)[1:] + "\n")
        print('Writing new values succeeded. Please run unit tests to make sure that nothing has broken.')
    else:
        print('Message_type_mapping.py content identical.')
